package ai.taskforge.api;
import ai.taskforge.domain.*; import ai.taskforge.repo.*; import ai.taskforge.service.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/tasks") public class TaskController { private final TaskRepository tasks;private final UserRepository users;private final ProjectRepository projects;private final CurrentUser current; public TaskController(TaskRepository t,UserRepository u,ProjectRepository p,CurrentUser c){tasks=t;users=u;projects=p;current=c;} record TaskInput(@NotBlank String title,String description,TaskStatus status,Priority priority,LocalDate dueDate,UUID assigneeId,UUID projectId,String category,Integer priorityScore){} record TaskView(UUID id,String title,String description,TaskStatus status,Priority priority,int priorityScore,LocalDate dueDate,String assignee,String project,String category,boolean aiGenerated,List<UUID> dependencyIds){} @GetMapping List<TaskView> list(){var u=current.get();return tasks.findAllBy().stream().filter(t->current.elevated()||t.getAssignee()==null||t.getAssignee().getId().equals(u.getId())||t.getDependencies().stream().anyMatch(d->d.getAssignee()!=null&&d.getAssignee().getId().equals(u.getId()))).map(this::view).toList();} @PostMapping TaskView create(@Valid @RequestBody TaskInput in){var t=new Task(in.title(),in.description(),current.get());apply(t,in);return view(tasks.save(t));} @PutMapping("/{id}") TaskView update(@PathVariable UUID id,@Valid @RequestBody TaskInput in){var t=tasks.findById(id).orElseThrow(()->new ApiException("NOT_FOUND","Task not found."));if(!current.elevated() && (t.getAssignee()==null||!t.getAssignee().getId().equals(current.get().getId())))throw new ApiException("FORBIDDEN","You cannot update this task.");if(in.status()==TaskStatus.COMPLETED&&t.getDependencies().stream().anyMatch(d->d.getStatus()!=TaskStatus.COMPLETED))throw new ApiException("DEPENDENCY_BLOCKED","Complete required dependencies first.");apply(t,in);return view(tasks.save(t));} @PostMapping("/{id}/dependencies/{dependencyId}") TaskView dependency(@PathVariable UUID id,@PathVariable UUID dependencyId){if(!current.elevated())throw new ApiException("FORBIDDEN","Only managers can set dependencies.");var t=tasks.getReferenceById(id);var d=tasks.getReferenceById(dependencyId);if(id.equals(dependencyId))throw new ApiException("INVALID_DEPENDENCY","A task cannot depend on itself.");t.addDependency(d);return view(tasks.save(t));} private void apply(Task t,TaskInput i){AppUser a=i.assigneeId()==null?null:users.findById(i.assigneeId()).orElseThrow(()->new ApiException("ASSIGNEE_NOT_FOUND","Assignee not found."));Project p=i.projectId()==null?null:projects.findById(i.projectId()).orElseThrow(()->new ApiException("PROJECT_NOT_FOUND","Project not found."));t.update(i.title(),i.description(),i.status()==null?TaskStatus.TODO:i.status(),i.priority()==null?Priority.MEDIUM:i.priority(),i.dueDate(),a,p,i.category(),i.priorityScore()==null?0:i.priorityScore());} private TaskView view(Task t){return new TaskView(t.getId(),t.getTitle(),t.getDescription(),t.getStatus(),t.getPriority(),t.getPriorityScore(),t.getDueDate(),t.getAssignee()==null?null:t.getAssignee().getDisplayName(),t.getProject()==null?null:t.getProject().getName(),t.getCategory(),t.isAiGenerated(),t.getDependencies().stream().map(Task::getId).toList());} }
